use ark_bn254::{Fq as Aq,Fr as Ar};
use ark_ff::{BigInteger,Field,PrimeField};
use num_bigint::{BigInt as Z,Sign};
use zopro_bn254::{FpConfig,FqConfig,FrConfig,ifma8::{Ifma8,UncarriedSum8}};
fn z(n:u64)->Z{Z::from(n)}
fn words(w:[u64;4])->Z{Z::from_bytes_le(Sign::Plus,&w.into_iter().flat_map(u64::to_le_bytes).collect::<Vec<_>>())}
fn w(x:&Z)->[u64;4]{let(s,v)=x.to_u64_digits();assert_ne!(s,Sign::Minus);assert!(v.len()<=4);let mut a=[0;4];a[..v.len()].copy_from_slice(&v);a}
fn md(x:Z,p:&Z)->Z{let r=x%p;if r<z(0){r+p}else{r}}
fn af<A:PrimeField>(x:&Z)->A{let(s,b)=x.to_bytes_le();let a=A::from_le_bytes_mod_order(&b);if s==Sign::Minus{-a}else{a}}
fn ai<A:PrimeField>(x:A)->Z{Z::from_bytes_le(Sign::Plus,&x.into_bigint().to_bytes_le())}
fn next(s:&mut u64)->u64{*s^=*s<<13;*s^=*s>>7;*s^=*s<<17;*s}
fn rnd(s:&mut u64,p:&Z)->Z{words(std::array::from_fn(|_|next(s)))%p}
#[unsafe(no_mangle)]#[inline(never)]pub fn actual_linear_original_canonical(a:&Ifma8<FqConfig,true>,x:&Ifma8<FqConfig,true>,y:&Ifma8<FqConfig,true>)->Ifma8<FqConfig,true>{a.sub(&x.add_canonical(y))}
#[unsafe(no_mangle)]#[inline(never)]pub fn actual_linear_original_generic(a:&Ifma8<FqConfig,true>,x:&Ifma8<FqConfig,true>,y:&Ifma8<FqConfig,true>)->Ifma8<FqConfig,true>{a.sub(&x.add(y))}
#[unsafe(no_mangle)]#[inline(never)]pub fn actual_linear_fused(a:&Ifma8<FqConfig,true>,x:&Ifma8<FqConfig,true>,y:&Ifma8<FqConfig,true>)->Ifma8<FqConfig,true>{UncarriedSum8::from_canonical(x,y).subtract_from(a)}
#[unsafe(no_mangle)]#[inline(never)]pub fn actual_linear_deferred_construct(x:&Ifma8<FqConfig,true>,y:&Ifma8<FqConfig,true>)->UncarriedSum8<FqConfig,true>{UncarriedSum8::from_canonical(x,y)}
#[unsafe(no_mangle)]#[inline(never)]pub fn actual_linear_deferred_consume(s:&UncarriedSum8<FqConfig,true>,a:&Ifma8<FqConfig,true>)->Ifma8<FqConfig,true>{s.subtract_from(a)}
fn digits(x:&Z,base:&Z)->[Z;5]{std::array::from_fn(|j|(x>>(52*j))%base)}
fn edges(bound:&Z)->Vec<Z>{let mut e=vec![z(0),z(1),bound-z(1)];for bit in[26,51,52,53,64,103,104,127,155,156,191,207,208,251,253]{for delta in[-1i64,0,1]{let x=(z(1)<<bit)+Z::from(delta);if x>=z(0)&&x<*bound{e.push(x);}}}e.sort();e.dedup();e}
fn check<C:FpConfig,A:PrimeField,const M:bool>()->(usize,usize,usize){
 let p=words(C::P);assert_eq!(p,Z::from_bytes_le(Sign::Plus,&A::MODULUS.to_bytes_le()));let two=&p*z(2);let base=z(1)<<52;let scale=if M{A::ONE}else{A::from(16u64).inverse().unwrap()};let ea=edges(&two);let eb=edges(&p);let n=eb.len();let boundary=ea.len()*n*n;let rows=boundary+2048+1024;let mut rng=0x6c696e6561722d63;let mut chain:[Z;8]=std::array::from_fn(|_|z(0));let mut count=0;let mut oversized=0;let mut minus_two=0;let mut neg=0;let mut nonneg=0;
 for row in 0..rows{
 let values:[[Z;8];3]=if row<boundary{std::array::from_fn(|j|std::array::from_fn(|i|match j{0=>ea[(row/(n*n)+i)%ea.len()].clone(),1=>eb[(row/n+3*i)%n].clone(),_=>eb[(row+5*i)%n].clone()}))}else{std::array::from_fn(|j|std::array::from_fn(|i|if row>=boundary+2048&&j==0{chain[i].clone()}else{rnd(&mut rng,if j==0{&two}else{&p})}))};
 let v:[Ifma8<C,M>;3]=std::array::from_fn(|j|Ifma8::linear_diagnostic_raw(&values[j].each_ref().map(|x|w(x)),j!=0));let sum=UncarriedSum8::from_canonical(&v[1],&v[2]);let sumdigits=sum.diagnostic_digits();let result=sum.subtract_from(&v[0]);let raw=result.linear_diagnostic_digits();let original=v[0].sub(&v[1].add_canonical(&v[2]));let generic=v[0].sub(&v[1].add(&v[2]));assert_eq!(raw,original.linear_diagnostic_digits());assert_eq!(raw,generic.linear_diagnostic_digits());let exported=result.get();
 for i in 0..8{let a=&values[0][i];let x=&values[1][i];let y=&values[2][i];let ad=digits(a,&base);let xd=digits(x,&base);let yd=digits(y,&base);let mut carry=Z::from(0);for j in 0..5{assert_eq!(Z::from(sumdigits[j][i]),&xd[j]+&yd[j]);oversized+=usize::from(Z::from(sumdigits[j][i])>=base);let q=&ad[j]-Z::from(sumdigits[j][i])+&carry;let rem=md(q.clone(),&base);carry=(q-rem)/&base;minus_two+=usize::from(carry==Z::from(-2));assert!(carry>=Z::from(-2)&&carry<=z(0));}assert!(carry==Z::from(-1)||carry==z(0));let diff=a-x-y;if diff<z(0){neg+=1;assert_eq!(carry,Z::from(-1));}else{nonneg+=1;assert_eq!(carry,z(0));}
 let value:Z=raw.iter().enumerate().map(|(j,v)|{assert!(v[i]<(1<<52));Z::from(v[i])<<(52*j)}).sum();let expected=md(diff,&two);assert_eq!(value,expected);assert!(value>=z(0)&&value<two);let host=words(exported[i].0);assert!(host<p);assert_eq!(host,ai((af::<A>(a)-af::<A>(x)-af::<A>(y))*scale));chain[i]=value;count+=1;}
 }
 assert!(oversized>0&&minus_two>0&&neg>0&&nonneg>0);println!("LINEAR_NATIVE prime={} radix={} canonical_edges={n} minuend_edges={} boundary_rows={boundary} random_rows=2048 chain_rows=1024 rows={rows} outputs={count} oversized_digits={oversized} internal_minus_two={minus_two} negative={neg} nonnegative={nonneg}",if C::P==FqConfig::P{"Fq"}else{"Fr"},if M{256}else{260},ea.len());(count,oversized,minus_two)
}
#[test]fn exact_raw_native_all_fields_radices_and_chains(){let rows=[check::<FqConfig,Aq,true>(),check::<FqConfig,Aq,false>(),check::<FrConfig,Ar,true>(),check::<FrConfig,Ar,false>()];println!("LINEAR_NATIVE_TOTAL outputs={} oversized={} minus_two={}",rows.iter().map(|x|x.0).sum::<usize>(),rows.iter().map(|x|x.1).sum::<usize>(),rows.iter().map(|x|x.2).sum::<usize>());let a=Ifma8::new(&[zopro_bn254::Fq::from(31);8]);let x=Ifma8::new(&[zopro_bn254::Fq::from(7);8]);let y=Ifma8::new(&[zopro_bn254::Fq::from(13);8]);let expected=actual_linear_original_canonical(&a,&x,&y).get();assert_eq!(actual_linear_original_generic(&a,&x,&y).get(),expected);assert_eq!(actual_linear_fused(&a,&x,&y).get(),expected);let sum=actual_linear_deferred_construct(&x,&y);assert_eq!(actual_linear_deferred_consume(&sum,&a).get(),expected);println!("LINEAR_ACTUAL_WRAPPERS checks=4");}
#[test]fn small_radix_exhaustive_and_ifma_width_counterexample(){let mut cases=0u64;let mut minus_two=0u64;for(bits,limbs,ps)in[(1u32,5u32,vec![3i128,5,7,11,13]),(2,3,vec![17,29]),(3,3,vec![31,61,127])]{let b=1i128<<bits;let modulus=1i128<<(bits*limbs);for p in ps{assert!(2*p<modulus);for a in 0..2*p{for x in 0..p{for y in 0..p{let mut carry=0;let mut low=0;for j in 0..limbs{let shift=j*bits;let s=((x>>shift)&(b-1))+((y>>shift)&(b-1));let v=((a>>shift)&(b-1))-s+carry;let digit=v.rem_euclid(b);carry=v.div_euclid(b);minus_two+=u64::from(carry== -2);assert!((-2..=0).contains(&carry));low+=digit<<shift;}assert!(carry== -1||carry==0);let output=(low+if carry<0{2*p}else{0})%modulus;assert_eq!(output,(a-x-y).rem_euclid(2*p));cases+=1;}}}}}
 let b=1u128<<52;let sum=2*(b-1);let truncated=sum&(b-1);assert_eq!(sum-truncated,b);let p=words(FqConfig::P);assert_ne!(md(Z::from(sum)-Z::from(truncated),&p),z(0));assert!(minus_two>0);println!("LINEAR_SMALL exhaustive={cases} minus_two={minus_two} invalid_IFMA_operand_counterexamples=1");}
